    if (b) { b.textContent = l[0]; b.className = 'badge' + (l[1] === 'current' ? ' badge--hot' : l[1] === 'past' ? ' badge--off' : ''); }
    if (a) {
      if (l[1] === 'past') a.hidden = true;
      else if (l[1] === 'future') a.hidden = true;   // only the open season gets a button: all attention on registering now
    }
